mapper.select:
SELECT sr.id, sr.application_id, a.student_id, s.student_no, s.name AS student_name, a.type_id, t.type_name, sr.economic_score, sr.family_burden_score, sr.special_hardship_score, sr.disaster_score, sr.scorer_id, tu.name AS scorer_name, sr.score_comment, sr.score_time, sr.create_time, sr.update_time FROM score_record sr LEFT JOIN grant_application a ON sr.application_id = a.id LEFT JOIN student s ON a.student_id = s.id LEFT JOIN grant_type t ON a.type_id = t.id LEFT JOIN sys_user tu ON sr.scorer_id = tu.user_id AND tu.role = 1
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%'))
AND a.type_id = #{typeId}
AND sr.scorer_id = #{scorerId}
ORDER BY sr.score_time DESC
